#include <fstream>
#include <queue>
#include <vector>
using namespace std;
int main() {
    ifstream input("lightson.in");
    ofstream output("lightson.out");
    int n, m;
    if (!(input >> n >> m)) return 0;
    vector<vector<int>> switches(n * n);
    for (int i = 0; i < m; ++i) {
        int x, y, a, b;
        input >> x >> y >> a >> b;
        switches[(x - 1) * n + y - 1].push_back((a - 1) * n + b - 1);
    }
    vector<char> lit(n * n), reached(n * n);
    queue<int> work;
    lit[0] = reached[0] = true;
    work.push(0);
    int answer = 1;
    auto neighbors = [&](int v) {
        vector<int> result;
        int x = v / n, y = v % n;
        if (x > 0) result.push_back(v - n);
        if (x + 1 < n) result.push_back(v + n);
        if (y > 0) result.push_back(v - 1);
        if (y + 1 < n) result.push_back(v + 1);
        return result;
    };
    while (!work.empty()) {
        int v = work.front();
        work.pop();
        for (int target : switches[v]) {
            if (!lit[target]) {
                lit[target] = true;
                ++answer;
                for (int u : neighbors(target)) {
                    if (reached[u] && !reached[target]) {
                        reached[target] = true;
                        work.push(target);
                    }
                }
            }
        }
        for (int u : neighbors(v)) {
            if (lit[u] && !reached[u]) {
                reached[u] = true;
                work.push(u);
            }
        }
    }
    output << answer << '\n';
}
