#include <fstream>
#include <vector>
using namespace std;
int main() {
    ifstream input("highcard.in");
    ofstream output("highcard.out");
    int n;
    if (!(input >> n)) return 0;
    vector<char> elsie(2 * n + 1);
    for (int i = 0; i < n; ++i) {
        int rank;
        input >> rank;
        elsie[rank] = true;
    }
    int pending = 0, wins = 0;
    for (int rank = 1; rank <= 2 * n; ++rank) {
        if (elsie[rank]) ++pending;
        else if (pending > 0) {
            --pending;
            ++wins;
        }
    }
    output << wins << '\n';
}
