#include <array>
#include <fstream>
#include <vector>
using namespace std;
int main() {
    ifstream input("bcount.in");
    ofstream output("bcount.out");
    int n, q;
    if (!(input >> n >> q)) return 0;
    vector<array<int, 3>> prefix(n + 1);
    prefix[0] = {0, 0, 0};
    for (int i = 1; i <= n; ++i) {
        int breed;
        input >> breed;
        prefix[i] = prefix[i - 1];
        ++prefix[i][breed - 1];
    }
    for (int i = 0; i < q; ++i) {
        int a, b;
        input >> a >> b;
        for (int breed = 0; breed < 3; ++breed) {
            if (breed) output << ' ';
            output << prefix[b][breed] - prefix[a - 1][breed];
        }
        output << '\n';
    }
}
